rows[51676]={title={{13,154318007},"결단력 저하"},description={"^increases the time between an enemy's attacks speed by ([%+%-]?%d[%d,.%+%-to –]*)%%, slows its casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%%, and slows its movement by ([%+%-]?%d[%d,.%+%-to –]*)%%%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","\0314\031 동안 적의 공격 간격을 \0311\031%만큼 늘이고 시전 속도를 \0312\031%만큼, 이동 속도를 \0313\031%만큼 저하시킵니다.",{0,0,0,1},{1,2,3,4}},aura={"^time between attacks increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. casting speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격 간격 \0311\031%만큼 늘어남\010주문 시전 속도 \0312\031%만큼 감소\010이동 속도 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
rows[51678]={title={{3,1969170},"들이받기"},description={"^rams any enemies in front of the demolisher, dealing ([%+%-]?%d[%d,.%+%-to –]*) damage and knocking them back%. also deals ([%+%-]?%d[%d,.%+%-to –]*) siege damage to buildings%.$","전방의 적을 들이받아 \0311\031의 피해를 입히고 뒤로 밀쳐냅니다. 건물에는 \0312\031의 공성 피해를 입힙니다.",{0,0},{1,2}}}
rows[51681]={title={{13,216300916},"뒷발 구르기"},description={"^stomps the ground, inflicting ([%+%-]?%d[%d,.%+%-to –]*)%% normal damage to nearby enemies and dazes nearby$","땅을 울려 주위 적에게 일반 공격력의 \0311\031%에 해당하는 피해를 입히고 멍하게 만듭니다.",{0},{1}},aura={"^movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
rows[51690]={title={{13,581017621},"광기의 학살자"},description={"^step through the shadows to an enemy within 10 yards, attacking it every ([%+%-]?%d[%d,.%+%-to –]*) sec with both weapons until 7 assaults are made, and increasing all damage done by ([%+%-]?%d[%d,.%+%-to –]*)%% for the duration%. cannot hit invisible or stealthed targets%. |cffffffffblade flurry effect:|r killing spree will teleport to and damage a nearby enemy target every ([%+%-]?%d[%d,.%+%-to –]*) sec instead of focusing on your primary target%.$","적의 그림자 속을 움직이며 10미터 이내로 다가가, 총 7번까지 \0311\031초마다 쌍수로 적을 공격합니다. 효과가 지속되는 동안 모든 공격력이 \0312\031%만큼 증가합니다. 투명화 및 은신 상태인 대상은 공격할 수 없습니다.\010\010|CFFFFFFFF폭풍의 칼날 효과:|R 광기의 학살자 사용 시 주 대상에게만 집중하지 않고, \0313\031초마다 가까이 있는 적에게 순간이동해 피해를 입힙니다.",{0,0,0},{1,2,3}},aura={"^attacking an enemy every ([%+%-]?%d[%d,.%+%-to –]*) sec%. damage dealt increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0311\031초마다 적 공격\010공격력 \0312\031%만큼 증가",{0,0},{1,2}}}
