rows[52657]={title={{15,885175437},"시간의 소용돌이"},description={"^channels a vortex on the enemy, dealing ([%+%-]?%d[%d,.%+%-to –]*) arcane damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. and slowing movement, attack, and casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 소용돌이를 집중시켜 \0312\031초마다 \0311\031의 비전 피해를 입히고 \0314\031 동안 이동 속도, 공격 속도, 시전 속도를 \0313\031%만큼 감소시킵니다.",{0,0,0,1},{1,2,3,4}},aura={"^attack, casting, and movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. ([%+%-]?%d[%d,.%+%-to –]*) arcane damage dealt every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","공격 속도, 시전 속도, 이동 속도 \0311\031%만큼 감소\010\0313\031초마다 \0312\031의 비전 피해",{0,0,0},{1,2,3}}}
rows[52658]={title={{15,1893736045},"전하 과부하"},description={"^charges an enemy with energy, inflicting ([%+%-]?%d[%d,.%+%-to –]*) nature damage over ([%+%-]?%d[%d,.]* %a+) and periodically zaps it's nearby allies for ([%+%-]?%d[%d,.%+%-to –]*) nature damage%. after ([%+%-]?%d[%d,.]* %a+), an electrical explosion occurs causing an additional ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards and knocking them back%.$","적에게 전하를 방출시켜 \0312\031에 걸쳐 \0311\031의 자연 피해를 입히고 주기적으로 주위 아군에게 충격을 가하여 \0311\031의 자연 피해를 입히게 합니다. \0312\031 후 전기 폭발이 발생하여 \0316\031미터 반경 내에 있는 모든 적에게 추가로 \0315\031의 자연 피해를 입히고 뒤로 밀쳐냅니다.",{0,1,0,1,0,0},{1,2,1,2,5,6}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) damage to surrounding allies every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 주위 아군에게 \0311\031의 피해",{0,0},{1,2}}}
