rows[53337]={title={{15,1893736045},"전하 과부하"},description={"^charges an enemy with energy, inflicting ([%+%-]?%d[%d,.%+%-to –]*) nature damage over ([%+%-]?%d[%d,.]* %a+) and periodically zaps it's nearby allies for ([%+%-]?%d[%d,.%+%-to –]*) nature damage%. after ([%+%-]?%d[%d,.]* %a+), an electrical explosion occurs causing an additional ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards and knocking them back%.$","적에게 전하를 방출시켜 \0312\031에 걸쳐 \0311\031의 자연 피해를 입히고 주기적으로 주위 아군에게 충격을 가하여 \0311\031의 자연 피해를 입히게 합니다. \0312\031 후 전기 폭발이 발생하여 \0316\031미터 반경 내에 있는 모든 적에게 추가로 \0315\031의 자연 피해를 입히고 뒤로 밀쳐냅니다.",{0,1,0,1,0,0},{1,2,1,2,5,6}}}
rows[53341]={title={{21,2048182110},"잿더미 빙하의 룬"},description={"^affixes your rune weapon with a rune that has a chance to increase the damage by ([%+%-]?%d[%d,.%+%-to –]*)%% for your next 2 attacks that deal frost or shadow damage%. modifying your rune weapon requires a rune forge in ebon hold%.$","룬 무기에 룬을 새깁니다. 일정 확률로 냉기 혹은 암흑 피해를 입히는 다음 2회 주문의 공격력이 \0311\031%만큼 증가합니다. 칠흑의 요새에 있는 룬가열로가 필요합니다.",{0},{1}}}
rows[53342]={title={{23,1870921410},"주문분쇄자의 룬"},description={"^affixes your two%-handed rune weapon with a rune that deflects ([%+%-]?%d[%d,.%+%-to –]*)%% of all spell damage and reduces the duration of silence effects by ([%+%-]?%d[%d,.%+%-to –]*)%%%. modifying your rune weapon requires a rune forge in ebon hold%.$","양손 룬 무기에 룬을 새깁니다. 받는 주문 피해 중 \0311\031%를 튕겨내고 침묵 효과의 지속시간이 \0312\031%만큼 감소합니다. 칠흑의 요새에 있는 룬가열로가 필요합니다.",{0,0},{1,2}}}
rows[53343]={title={{16,1592466276},"칼날얼음의 룬"},description={{205,2127876866},"무기에 룬을 새깁니다. 공격 시 무기 공격력의 2%에 해당하는 추가 냉기 피해를 입히고 대상이 받는 냉기 피해가 증가합니다. 칠흑의 요새에 있는 룬가열로가 필요합니다."}}
rows[53344]={title={{27,59155809},"타락한 성전사의 룬"},description={"^affixes your rune weapon with a rune that has a chance to heal you for ([%+%-]?%d[%d,.%+%-to –]*)%% and increase total strength by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. modifying your rune weapon requires a rune forge in ebon hold%.$","룬 무기에 룬을 새깁니다. 일정 확률로 생명력을 \0311\031%만큼 회복하고 \0313\031 동안 전체 힘이 \0312\031%만큼 증가합니다. 칠흑의 요새에 있는 룬가열로가 필요합니다.",{0,0,1},{1,2,3}}}
