rows[53549]={title={{9,1328669160},"얼음 손길"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*) to ([%+%-]?%d[%d,.%+%-to –]*) frost damage modified by attack power and reduces the target's ranged, melee attack, and casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","대상에게 \0311\031에서 \0312\031의 냉기 피해를 입히고 \0314\031 동안 대상의 근접 및 원거리 공격 속도, 주문 시전 속도를 \0313\031%만큼 감소시킵니다. 전투력에 따라 피해량이 달라집니다.",{0,0,0,1},{1,2,3,4}},aura={"^ranged, melee and casting speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","원거리, 근접, 주문 시전 속도 \0311\031%만큼 감소",{0},{1}}}
