rows[54021]={title={{12,115728348},"메뚜기 떼"},description={"^anub'rekhan releases a locust swarm, slowing his movement by ([%+%-]?%d[%d,.%+%-to –]*)%% and damaging all nearby enemies%. nearby enemies are unable to attack or cast spells%.$","아눕레칸이 메뚜기 떼를 불러냅니다. 이동 속도가 \0311\031%만큼 감소하고 주위 모든 적들에게 피해를 입힙니다. 주위 적들은 공격하거나 주문을 시전할 수 없습니다.",{0},{1}},aura={"^movement speed slowed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
