rows[54466]={title={{16,1332195862},"사로나이트 수류탄"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) fire damage and incapacitates targets for ([%+%-]?%d[%d,.]* %a+) in a 3 yard radius%. any damage will break the effect%. unreliable against targets higher than level 90%.$","3미터 반경에 \0311\031의 화염 피해를 입히고 대상을 \0312\031 동안 행동 불가 상태로 만듭니다. 대상이 피해를 입으면 효과가 사라집니다. 90 레벨을 초과한 대상에겐 제대로 효과를 발휘하지 못합니다.",{0,1},{1,2}}}
rows[54467]={title={{10,2062482925},"뼈 갑옷"},description={"^the bone gryphon is surrounded by 5 whirling bones%. while at least 1 bone remains, it takes 40%% less damage from all sources and deals ([%+%-]?%d[%d,.%+%-to –]*)%% more damage with all attacks, spells and abilities%. each spell or attack that lands consumes 1 bone%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","소용돌이치는 5개의 뼈가 해골 그리핀 주위에 머무릅니다. 뼈가 1개 이상 남아 있는 동안 모든 받는 피해가 40%만큼 감소하고 모든 공격력이 \0311\031%만큼 증가합니다. 공격을 받을 때마다 1개의 뼈가 사라집니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={{22,812061920},"받는 피해 40%만큼 감소"}}
