rows[54469]={title={{13,532181188},"역병의 일격"},description={"^a vicious strike that deals talon damage plus ([%+%-]?%d[%d,.%+%-to –]*) modified by attack power and plagues the target, dealing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage over ([%+%-]?%d[%d,.]* %a+)%. only useful versus onslaught gryphon riders%.$","발톱 공격력에 추가로 \0311\031의 피해를 입히고 대상을 감염시켜 \0313\031에 걸쳐 \0312\031의 암흑 피해를 입힙니다. 전투력에 따라 피해량이 달라집니다. 붉은돌격대 그리핀 기수에게만 사용할 수 있습니다.",{0,0,1},{1,2,3}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage over ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031에 걸쳐 \0311\031의 암흑 피해",{0,1},{1,2}}}
