rows[54476]={title={{14,159780128},"혈기의 형상"},description={"^strengthens the bone gryphon with the presence of blood, increasing damage by ([%+%-]?%d[%d,.%+%-to –]*)%% and healing the bone gryphon by ([%+%-]?%d[%d,.%+%-to –]*)%% of damage dealt%.$","혈기의 형상으로 해골 그리핀을 감싸 공격력을 \0311\031%만큼 증가시키고 입힌 피해의 \0312\031%만큼 해골 그리핀의 생명력이 회복되도록 합니다.",{0,0},{1,2}},aura={"^increases damage by ([%+%-]?%d[%d,.%+%-to –]*)%% and heals the bone gryphon by ([%+%-]?%d[%d,.%+%-to –]*)%% of damage dealt%. the bone gryphon has accelerated health regeneration outside of combat%.$","공격력 \0311\031%만큼 증가\010입힌 피해의 \0312\031%만큼 해골 그리핀의 생명력 회복\010전투 상태가 아닐 때 생명력 회복 속도 증가",{0,0},{1,2}}}
