rows[54780]={title={{13,1488040368},"역병 튀기기"},description={"^throws a plague bomb at a nearby target, dealing ([%+%-]?%d[%d,.%+%-to –]*) nature damage and ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec to the target and nearby enemy targets for ([%+%-]?%d[%d,.]* %a+)%.$","주위 대상에게 역병의 폭탄을 던져 \0311\031의 자연 피해를 입히고 \0314\031 동안 대상과 주위의 적에게 \0313\031초마다 \0312\031의 자연 피해를 입힙니다.",{0,0,0,1},{1,2,3,4}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 자연 피해",{0,0},{1,2}}}
rows[54781]={title={{13,827110803},"광포의 강하"},description={"^the casters leaps to the target and increases the attack speed of the caster by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","대상을 향해 도약합니다. 공격 속도가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^attack speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격 속도 \0311\031%만큼 증가",{0},{1}}}
