rows[54785]={title={{12,1722678035},"악마의 도약"},description={{106,969940440},"악마의 날개로 공중에 떠올라 짧은 거리를 이동합니다.\010\010이 능력을 사용하면 탈태 상태가 됩니다."}}
rows[54786]={title={{12,1722678035},"악마의 도약"},description={"^leap through the air ([%+%-]?%d[%d,.%+%-to –]*) yards in front of you, slamming down on all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the target area, causing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage and stunning them for ([%+%-]?%d[%d,.]* %a+)%.$","전방 \0311\031미터 앞으로 공중 도약 후 지면에 강력한 충격을 일으키며 \0312\031미터 반경 내에 있는 모든 적에게 \0313\031의 암흑 피해를 입히고 \0314\031 동안 기절시킵니다.",{0,0,0,1},{1,2,3,4}},aura={{8,318235535},"기절함"}}
