rows[54790]={title={{9,755271655},"혈기 전환"},description={"^inflicts physical damage and increases damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","물리 피해를 입히고 \0312\031 동안 공격력을 \0311\031%만큼 증가시킵니다.",{0,1},{1,2}},aura={"^damage increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격력 \0311\031%만큼 증가",{0},{1}}}
