rows[54792]={title={{9,1894983612},"얼음 핏줄"},description={"^hastens your spellcasting, increasing spell casting speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","주문 시전을 빠르게 하여 주문 시전 속도를 \0311\031%만큼 증가시킵니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^casting speed of all spells increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","주문 시전 속도 \0311\031%만큼 증가",{0},{1}}}
