rows[54794]={title={{5,22339674},"도발"},description={{90,812410009},"적을 도발하여 자신을 공격하게 만듭니다. 이미 자신을 공격하고 있다면 아무런 효과를 발휘하지 못합니다."},aura={{90,812410009},"적을 도발하여 자신을 공격하도록 만듭니다. 이미 자신을 공격하고 있다면 아무런 효과를 발휘하지 못합니다."}}
rows[54795]={title={{13,851387812},"부두 불길"},description={"^surrounds self with a shield of flame that inflicts ([%+%-]?%d[%d,.%+%-to –]*) fire damage to nearby enemies every ([%+%-]?%d[%d,.%+%-to –]*) sec%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","불길의 보호막으로 자신을 감싸 주위 적에게 \0312\031초마다 \0311\031의 화염 피해를 입힙니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^inflicting ([%+%-]?%d[%d,.%+%-to –]*) fire damage to nearby enemies every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","주위 적에게 \0312\031초마다 \0311\031의 화염 피해",{0,0},{1,2}}}
