rows[54797]={title={{9,1589838921},"소용돌이"},description={"^attacks nearby enemies in a whirlwind of steel that lasts ([%+%-]?%d[%d,.]* %a+)%. and inflicts normal damage plus ([%+%-]?%d[%d,.%+%-to –]*)%.$","\0311\031 동안 강철의 소용돌이로 주위 적을 공격하여 일반 공격력에 추가로 \0312\031의 피해를 입힙니다.",{1,0},{1,2}},aura={"^attacking all nearby enemies for normal damage plus ([%+%-]?%d[%d,.%+%-to –]*)%.$","주위의 모든 적에게 일반 공격력 +\0311\031의 피해",{0},{1}}}
