rows[54805]={title={{9,1364641331},"정신의 채찍"},description={"^inflicts shadow damage to an enemy and reduces its movement speed for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 암흑 피해를 입히고 \0311\031 동안 이동 속도를 감소시킵니다.",{1},{1}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) shadow damage inflicted every second for ([%+%-]?%d[%d,.]* %a+)%. movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0312\031에 걸쳐 1초마다 \0311\031의 암흑 피해\010이동 속도 \0313\031%만큼 감소",{0,1,0},{1,2,3}}}
