rows[54808]={title={{12,859656059},"음파 보호막"},description={"^melee attacks against you have a chance to invoke a sonic shield, absorbing ([%+%-]?%d[%d,.%+%-to –]*) damage%. this effect can only occur once a minute%.$","근접 공격을 받으면 일정 확률로 \0311\031의 피해를 흡수하는 음파 보호막이 활성화됩니다. 이 효과는 1분마다 1번씩만 발동됩니다.",{0},{1}}}
