rows[54811]={title={{13,838391969},"문양: 후려갈기기"},description={"^your maul ability now hits ([%+%-]?%d[%d,.%+%-to –]*) additional target for ([%+%-]?%d[%d,.%+%-to –]*)%% damage%.$","후려갈기기 시 추가로 \0311\031명을 더 공격하여 \0312\031%의 피해를 입힙니다.",{0,0},{1,2}}}
rows[54812]={title={{14,923384677},"문양: 전조"},description={"^while you are not in an eclipse, the following abilities now grant ([%+%-]?%d[%d,.%+%-to –]*) solar or lunar energy: entangling roots, cyclone, faerie fire, faerie swarm, mass entanglement, typhoon, disorienting roar, ursol's vortex, and mighty bash%.$","일식 또는 월식이 아닐 때 다음 능력들이 \0311\031의 태양 또는 달 에너지를 생성합니다: 휘감는 뿌리, 회오리바람, 요정의 불꽃, 요정 떼, 대규모 휘감기, 태풍, 혼란의 포효, 우르솔의 회오리, 거센 강타.",{0},{1}}}
rows[54814]={title={{7,608090861},"신경 마비"},description={"^increases the time between an enemy's attacks by ([%+%-]?%d[%d,.%+%-to –]*)%% and its movement by ([%+%-]?%d[%d,.%+%-to –]*)%%, in addition to reducing its strength by ([%+%-]?%d[%d,.%+%-to –]*)%%%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","적의 공격 간격을 \0311\031%만큼 늘이고 이동 속도를 \0312\031%만큼, 힘을 \0313\031%만큼 감소시킵니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}},aura={"^movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. time between attacks increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. strength reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소\010공격 간격 \0312\031%만큼 늘어남\010체력 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
