rows[54819]={title={{16,1882589963},"모조 적시기"},description={"^surge through enemies in a line, drenching them%. deals immediate nature damage and additional damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%.$","직선상의 적들을 공격하여 모조에 젖게 합니다. 즉시 자연 피해를 입히고 \0312\031 동안 \0311\031초마다 추가 피해를 입힙니다.",{0,1},{1,2}},aura={"^nature damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0311\031초마다 자연 피해",{0},{1}}}
