rows[54831]={title={{18,1014257511},"문양: 싹쓸바람"},description={"^your hurricane and astral storm abilities now also slow the movement speed of their victims by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","싹쓸바람과 천공의 폭풍 주문이 대상의 이동 속도를 \0311\031%만큼 감소시킵니다.",{0},{1}}}
rows[54832]={title={{18,470381714},"문양: 정신 자극"},description={"^when innervate is cast on a target other than the caster, both the caster and target will benefit, but at ([%+%-]?%d[%d,.%+%-to –]*)%% reduced effect%.$","시전자 외의 대상에게 정신 자극을 시전할 경우 대상과 시전자 모두에게 효과가 적용되지만, 효과가 \0311\031%만큼 감소합니다.",{0},{1}}}
rows[54833]={title={{9,1435476862},"정신 자극"},description={"^causes the caster to regenerate equal to ([%+%-]?%d[%d,.%+%-to –]*)%% of spirit %(excluding short%-duration spirit bonuses%) every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%.$","시전자가 \0313\031에 걸쳐 \0312\031초마다 정신력(단기 정신력 보너스 제외)의 \0311\031%에 해당하는 마나를 회복합니다.",{0,0,1},{1,2,3}},aura={"^regenerating ([%+%-]?%d[%d,.%+%-to –]*) mana every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%.$","\0313\031 동안 \0312\031초마다 \0311\031의 마나 회복",{0,0,1},{1,2,3}}}
rows[54835]={title={{26,120630717},"역병술사의 저주"},description={{216,1798526533},"대상을 역병술사의 저주로 저주합니다. 만약 대상이 이 저주를 해제하지 않으면 대상은 선택된 지역에 있는 아군과 함께 역병술사의 천벌에 감염됩니다."},aura={{25,1743759800},"역병이 다가오고 있습니다..."}}
rows[54836]={title={{26,979262485},"역병술사의 천벌"},description={"^infects nearby allies, inflicting ([%+%-]?%d[%d,.%+%-to –]*) shadow damage, then an additional ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. for ([%+%-]?%d[%d,.]* %a+)%.$","주위 아군을 감염시켜 \0311\031의 암흑 피해를 입히고 \0314\031에 걸쳐 \0313\031초마다 \0312\031의 추가 피해를 입힙니다.",{0,0,0,1},{1,2,3,4}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 암흑 피해",{0,0},{1,2}}}
