rows[54838]={title={{15,1894672456},"정화된 정신"},description={"^chance on spell hit to increase your spirit by ([%+%-]?%d[%d,.%+%-to –]*) for 10 secs%.$","주문 적중 시 일정 확률로 10초 동안 정신력이 \0311\031만큼 증가합니다.",{0},{1}}}
rows[54839]={title={{15,1894672456},"정화된 정신"},description={"^increases spirit by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 정신력이 \0311\031만큼 증가합니다.",{0,1},{1,2}},aura={"^spirit increased by ([%+%-]?%d[%d,.%+%-to –]*)%.$","정신력 \0311\031만큼 증가",{0},{1}}}
rows[54840]={title={{13,1535375112},"탈태"},description={"^you transform into into a demon, increasing your armor by ([%+%-]?%d[%d,.%+%-to –]*)%% and reducing the duration of stun and snare effects on you by ([%+%-]?%d[%d,.%+%-to –]*)%%%. while in demon form, you cannot cast spells, but you gain unique demon abilities%.$","악마의 모습으로 변신합니다. 방어도가 \0311\031%만큼 증가하고 기절과 감속 효과의 지속시간이 \0312\031%만큼 감소합니다.\010\010악마 형상 상태에서는 주문을 시전할 수 없고 악마의 능력을 사용할 수 있습니다.",{0,0},{1,2}},aura={{149,2125281623},"악마 형상으로 방어도 360%만큼 증가\010기절과 감속 효과의 지속시간 50%만큼 감소\010악마의 능력 사용"}}
rows[54841]={title={{17,1463177835},"천둥 축전기"},description={"^you gain a thunder charge each time you cause a damaging spell critical strike%. when you reach ([%+%-]?%d[%d,.%+%-to –]*) thunder charges, they will release, firing a lightning bolt for ([%+%-]?%d[%d,.%+%-to –]*) damage%. thunder charge cannot be gained more often than once every 2%.5 sec%.$","공격 주문이 극대화 효과를 발휘한 경우 천둥 충전 효과를 얻습니다. \0311\031회 충전되면 번개 화살을 발사하여 \0312\031의 피해를 입힙니다. 천둥은 2.5초마다 1회 이상 충전되지 않습니다.",{0,0},{1,2}}}
rows[54842]={title={{14,798917537},"천둥 충전"},description={{32,2145052068},"천둥을 숨기는 데 효과적입니다."},aura={{32,2145052068},"천둥을 숨기는 데 효과적입니다."}}
