rows[55974]={title={{10,116112850},"피의 소용돌이"},description={"^causes all disease effects on targets within ([%+%-]?%d[%d,.%+%-to –]*) yards to painfully erupt, consuming the diseases, dealing ([%+%-]?%d[%d,.%+%-to –]*) to ([%+%-]?%d[%d,.%+%-to –]*) damage modified by attack power, and forcing the target to attack the death knight for ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031미터 반경 내에 있는 모든 대상에 걸려 있는 질병을 고통스럽게 폭발시켜 \0312\031~\0313\031의 암흑 피해를 입히고 \0314\031 동안 죽음의 기사를 공격하도록 만듭니다. 전투력에 따라 피해량이 달라집니다.",{0,0,0,1},{1,2,3,4}},aura={{8,569239999},"도발당함"}}
rows[55975]={title={{8,1778023368},"격분"},description={"^induces a friendly unit into a killing frenzy for ([%+%-]?%d[%d,.]* %a+), increasing their physical damage by ([%+%-]?%d[%d,.%+%-to –]*)%%, but causing them to suffer damage equal to ([%+%-]?%d[%d,.%+%-to –]*)%% of their maximum health every second%.$","우호적인 대상을 \0311\031 동안 죽음의 광란에 빠뜨립니다. 대상은 물리 공격력이 \0312\031%만큼 증가하지만 1초마다 최대 생명력의 \0313\031%에 해당하는 피해를 입습니다.",{1,0,0},{1,2,3}},aura={"^physical damage increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. damage equal to ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health every sec%.$","물리 공격력 \0311\031%만큼 증가\0101초마다 최대 생명력의 \0312\031%만큼 피해",{0,0},{1,2}}}
rows[55976]={title={{16,717149180},"주문 회피"},description={"^attacks nearby enemies in a whirlwind of steel that lasts ([%+%-]?%d[%d,.]* %a+)%., inflicting weapon damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. grants the caster temporary magic immunity%.$","\0311\031 동안 강철의 소용돌이로 주위 적을 공격하여 \0312\031초마다 무기 공격력만큼의 피해를 입힙니다. 일시적으로 마법 공격에 면역이 됩니다.",{1,0},{1,2}},aura={"^reflecting magic%. inflicting normal damage every ([%+%-]?%d[%d,.%+%-to –]*) sec to nearby enemies%.$","마법 주문 반사\010주위 적에게 \0311\031초마다 일반 공격력의 피해",{0},{1}}}
