rows[56706]={title={{13,878412441},"턱뼈 벌리기"},description={"^pry open the jaws of the wild wyrm, exposing its throat%. increases chance to hit with fatal strike by ([%+%-]?%d[%d,.%+%-to –]*)%% per application%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","야생 고룡의 턱뼈를 벌려 목까지 드러나게 합니다. 턱뼈를 벌릴 때마다 치명적 일격으로 공격할 확률이 \0311\031%만큼 증가합니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^the wild wyrm's jaws are pried open ([%+%-]?%d[%d,.%+%-to –]*) degrees%.$","\0311\031도만큼 야생 고룡의 턱뼈를 벌림",{0},{1}}}
rows[56707]={title={{16,1985836549},"부패의 질병"},description={"^increases the time betwen an enemy's attacks by ([%+%-]?%d[%d,.%+%-to –]*)%% and its casting by ([%+%-]?%d[%d,.%+%-to –]*)%%, as well as adding ([%+%-]?%d[%d,.%+%-to –]*)%% chance to spread the contagion to an ally when hit%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","\0314\031 동안 공격 간격을 \0311\031%만큼 늘이고 시전 시간을 \0312\031%만큼 증가시킵니다. 공격을 받을 때 \0313\031%의 확률로 같은 질병을 아군에게 퍼뜨립니다.",{0,0,0,1},{1,2,3,4}},aura={"^time between attacks increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. casting speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. ([%+%-]?%d[%d,.%+%-to –]*)%% chance to spread contagion to allies when hit%.$","공격 간격 \0311\031%만큼 늘어남\010주문 시전 속도 \0312\031%만큼 감소\010\0313\031%의 확률로 공격 받을 시 아군에게 전염",{0,0,0},{1,2,3}}}
